/**
 * The JavaScript half of the shared conformance contract.
 *
 * `shared/fixtures/` is generated by `scripts/build-data.ts` and read by BOTH
 * test suites — this file, and `packages/python/tests/test_shared_fixtures.py`.
 * The point is not to re-test the JS package: every assertion here is already
 * covered somewhere in `tests/`. The point is that the fixture files are a
 * TRUE description of this implementation's behaviour, because the Python
 * package is verified against nothing but them.
 *
 * Without this file the fixtures could drift into being a description of
 * nothing: `--check` proves they match what the generator produces, but the
 * generator is not the shipped library. If a refactor changed `search()` and
 * the fixtures were regenerated in the same commit, `--check` would stay green
 * and Python would follow the change — which is correct. If instead someone
 * hand-edited a fixture to make a Python test pass, `--check` catches it. This
 * file closes the remaining gap: the fixtures describe the real exported API,
 * not the generator's private copy of the rules.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import { slug } from "../scripts/build-data";
import { normalize } from "../packages/js/src/normalize";
import { getCommunes, getDairas, getWilayas, search } from "../packages/js/src/index";

const FIXTURES = join(import.meta.dirname, "..", "shared", "fixtures");

function fixture<T>(name: string): T {
  return JSON.parse(readFileSync(join(FIXTURES, `${name}.json`), "utf8")) as T;
}

describe("shared/fixtures/ids.json", () => {
  const ids = fixture<{ dairas: string[]; communes: string[] }>("ids");

  it("lists every daira and commune id in document order", () => {
    expect(ids.dairas).toEqual(getDairas().map((daira) => daira.id));
    expect(ids.communes).toEqual(getCommunes().map((commune) => commune.id));
  });

  // The counts are stated separately from the deep-equal above so a size change
  // reports as "591 vs 590" rather than as a diff of 591 strings.
  it("is the 2132 synthesized ids, all unique", () => {
    expect(ids.dairas).toHaveLength(591);
    expect(ids.communes).toHaveLength(1541);
    expect(new Set(ids.dairas).size).toBe(591);
    expect(new Set(ids.communes).size).toBe(1541);
  });
});

describe("shared/fixtures/slug.json", () => {
  const slugs = fixture<{ cases: { input: string; expected: string }[] }>("slug");

  it.each(slugs.cases)("slug($input) === $expected", ({ input, expected }) => {
    expect(slug(input)).toBe(expected);
  });

  /**
   * The two cases the rule is most often reimplemented wrongly.
   *
   * A slug rule written as "lowercase, strip accents, drop apostrophes, turn
   * separators into hyphens" — which is how the rule reads in prose, and how it
   * was written in the design document — produces `b.-b.-arreridj` and
   * `zbarbar-(el-isseri-)`. Both are real records. The missing step is dropping
   * everything outside [a-z0-9-] AFTER the whitespace pass.
   */
  it("drops punctuation rather than turning it into a separator", () => {
    expect(slug("B. B. Arreridj")).toBe("b-b-arreridj");
    expect(slug("Z'barbar (El Isseri )")).toBe("zbarbar-el-isseri");
  });
});

describe("shared/fixtures/normalize.json", () => {
  const norm = fixture<{
    cases: { input: string; expected: string }[];
    keys: { count: number; distinct: number; sha256: string };
    refs: { count: number; sha256: string };
  }>("normalize");

  it.each(norm.cases)("normalize($input) === $expected", ({ input, expected }) => {
    expect(normalize(input)).toBe(expected);
  });

  it("agrees with the shipped key index on count and distinctness", () => {
    expect(norm.keys.count).toBe(4402);
    expect(norm.keys.distinct).toBe(3055);
    expect(norm.refs.count).toBe(norm.keys.count);
  });

  it("folds the Arabic letter classes that NFD alone cannot", () => {
    // Lossy on purpose: phone keyboards produce ha for ta marbuta and ya for
    // alef maqsura, and both must find the same record. The normalized form is
    // an internal index key and is never displayed.
    expect(normalize("بجاية")).toBe(normalize("بجايه"));
    expect(normalize("الجزائر الوسطى")).toBe(normalize("الجزاير الوسطي"));
    // These four come out of NFD plus the combining-mark strip, NOT an explicit
    // character map. An implementation that adds an explicit alef fold after
    // NFD gets a silent no-op, which is exactly what this asserts against.
    expect(normalize("أدرار")).toBe(normalize("ادرار"));
    expect(normalize("إدرار")).toBe(normalize("ادرار"));
    expect(normalize("آدرار")).toBe(normalize("ادرار"));
    expect(normalize("ٱدرار")).toBe(normalize("ادرار"));
  });
});

describe("shared/fixtures/ground-truth.json", () => {
  // Spelled out field by field rather than as Record<string, number>: an index
  // signature would make every read `number | undefined` under
  // noUncheckedIndexedAccess, and the repo bans `!` and `any` to silence that.
  const truth = fixture<{
    counts: {
      wilayas: number;
      dairas: number;
      communes: number;
      searchableRecords: number;
    };
    postalCodes: {
      present: number;
      missing: number;
      malformed: number;
      distinct: number;
      sharedByMoreThanOneCommune: number;
    };
    nameUniqueness: {
      communeWilayaNamePairs: number;
      distinctCommuneNames: number;
      dairaWilayaNamePairs: number;
      distinctDairaNames: number;
    };
    exonyms: string[];
    communesMissingPostalCode: string[];
    duplicatedCommuneNameExamples: { name: string; wilayas: number[] }[];
  }>("ground-truth");

  it("matches the shipped dataset", () => {
    expect(truth.counts.wilayas).toBe(getWilayas().length);
    expect(truth.counts.dairas).toBe(getDairas().length);
    expect(truth.counts.communes).toBe(getCommunes().length);

    const communes = getCommunes();
    const withPostal = communes.filter((commune) => commune.postalCode !== null);
    expect(truth.postalCodes.present).toBe(withPostal.length);
    expect(truth.postalCodes.missing).toBe(communes.length - withPostal.length);
    expect(truth.communesMissingPostalCode).toHaveLength(truth.postalCodes.missing);

    const postal = withPostal.map((commune) => commune.postalCode);
    expect(truth.postalCodes.distinct).toBe(new Set(postal).size);
    expect(truth.counts.searchableRecords).toBe(
      getWilayas().length + getDairas().length + getCommunes().length,
    );
    expect(truth.nameUniqueness.distinctCommuneNames).toBe(
      new Set(communes.map((commune) => commune.name.fr)).size,
    );
    expect(truth.nameUniqueness.distinctDairaNames).toBe(
      new Set(getDairas().map((daira) => daira.name.fr)).size,
    );
  });

  it("records the one exonym in 2201 records", () => {
    expect(truth.exonyms).toEqual(["Alger"]);
  });

  it("records the duplicated commune names by wilaya, not just by count", () => {
    // These are real data, not a defect: a result that is only a name is
    // undisambiguable, which is why every SearchResult carries its wilaya.
    expect(truth.duplicatedCommuneNameExamples).toEqual([
      { name: "Sidi Ameur", wilayas: [32, 64] },
      { name: "Souk El Had", wilayas: [35, 48] },
    ]);
  });
});

describe("the fixtures are not empty", () => {
  /**
   * Every other block here iterates a fixture's cases and asserts no failures,
   * and all of them pass vacuously against `{"cases": []}`. A regeneration that
   * silently emitted nothing would turn the whole conformance suite green in
   * BOTH languages while checking nothing — the one failure mode the shared
   * tier cannot afford, since it is the tier everything else trusts.
   *
   * Lower bounds, so adding a case never fails a test.
   */
  it("carries every case and every id", () => {
    expect(fixture<{ cases: unknown[] }>("slug").cases.length).toBeGreaterThanOrEqual(11);
    expect(fixture<{ cases: unknown[] }>("normalize").cases.length).toBeGreaterThanOrEqual(25);
    expect(fixture<{ cases: unknown[] }>("search").cases.length).toBeGreaterThanOrEqual(30);
    const ids = fixture<{ dairas: string[]; communes: string[] }>("ids");
    expect(ids.dairas).toHaveLength(591);
    expect(ids.communes).toHaveLength(1541);
  });

  it("carries the digests that make normalize.json exhaustive", () => {
    const norm = fixture<{ keys: { count: number; distinct: number; sha256: string } }>(
      "normalize",
    );
    expect(norm.keys.count).toBe(4402);
    expect(norm.keys.distinct).toBe(3055);
    expect(norm.keys.sha256).toHaveLength(64);
  });
});

describe("shared/fixtures/search.json", () => {
  const fx = fixture<{
    cases: {
      query: string;
      options: Record<string, unknown>;
      results: { kind: string; id: string; wilaya: number; score: number; matched: string }[];
    }[];
  }>("search");

  it("covers every folding rule and every tier", () => {
    expect(fx.cases.length).toBeGreaterThanOrEqual(30);
  });

  it.each(fx.cases.map((c, i) => ({ ...c, i })))(
    "case $i: search($query) reproduces the fixture",
    ({ query, options, results }) => {
      const actual = search(query, options as never).map((result) => ({
        kind: result.kind,
        id: result.kind === "wilaya" ? result.item.codeText : result.item.id,
        wilaya: result.wilaya.code,
        score: result.score,
        matched: result.matched,
      }));
      // Deep equality on the ORDER too, not just the set: the tie-break is part
      // of the contract, and a flaky order is untestable and looks broken in a
      // UI. Two identical calls must always produce identical output.
      expect(actual).toEqual(results);
    },
  );
});
